INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(7, 'frFR', 'Comment se passe la chasse, $N ? Avez-vous trouvé et vaincu cette vermine ?', 0),
(15, 'frFR', 'Avez-vous visité les mines ? Êtes-vous prêt à faire votre rapport ?', 0),
(21, 'frFR', 'Je sais que c''est un sacré boulot, $N, mais c''est vital pour la sécurité du Northshire. Êtes-vous prêt à faire votre rapport ?', 0),
(57, 'frFR', 'Revenez me voir quand vous aurez tué 15 monstres squelettiques et 15 horreurs squelettiques, $N.', 0),
(58, 'frFR', 'J''ai besoin de votre aide, $N. Allez au cimetière au nord-ouest et débarrassez le mausolée de l''est de 20 propagateurs de peste.$B$BRevenez me voir lorsque vous aurez terminé votre tâche.', 0),
(62, 'frFR', 'Qu''avez-vous à signaler, $N ? Avez-vous visité la mine de Fargodeep ?', 0),
(111, 'frFR', 'J''ai hâte de connaître la réaction de mes amis !$B$BIls ne s''y attendront jamais', 0),
(124, 'frFR', 'Mes chevaux sont toujours aussi nerveux et j''entends toujours ce maudit cri de loup la nuit. S''il vous plaît, $N, faites quelque chose pour ces Gnolls !', 0),
(152, 'frFR', 'Tuez 7 chasseurs de marées, 7 guerriers, 7 oracles et 7 coastrunners et je veillerai à ce que vous soyez récompensés.', 0),
(155, 'frFR', 'Quelle affaire avez-vous avec moi ? Je suis un homme très occupé...', 0),
(173, 'frFR', '$N, comment va la chasse?', 0),
(186, 'frFR', 'Si vous voulez relever de plus grands défis, vous devez d''abord faire vos preuves dans la tâche qui vous est confiée. Revenez me voir quand vous aurez tué 10 tigres de l''épine étranglée.', 0),
(187, 'frFR', 'Vous devez tuer 10 tigres anciens de l''épine étranglée avant que je ne vous lance le dernier défi qui déterminera si vous êtes un véritable maître de la chasse au tigre.', 0),
(191, 'frFR', 'Allez tuer 10 panthères ! Montre-nous ce que tu as dans le ventre !', 0),
(201, 'frFR', 'Alors ? Avez-vous réussi à localiser le camp ?', 0),
(216, 'frFR', 'Avez-vous porté le combat contre le Thistlefur ? Avec un chemin dégagé entre nos bases, nos chances de revendiquer l''ensemble d’Orneval augmentent considérablement.', 0),
(221, 'frFR', 'De retour si tôt, $N ? J''espère que tu n''es pas venu me dire que tu as abandonné.', 0),
(255, 'frFR', 'Avez-vous eu de la chance ?', 0),
(261, 'frFR', 'Le Fléau gagne en puissance au fil des jours. Si vous souhaitez vraiment stopper sa progression, montrez-moi.', 0),
(287, 'frFR', 'Vous ne le trouvez pas ? Mes indications étaient très claires ! Nous n''avons pas beaucoup de temps, vous devez vous dépêcher ! Ne revenez pas avant d''avoir trouvé la grotte.', 0),
(295, 'frFR', 'Je veux faire payer à ces Scytheclaws et Razormaws tachetés ce qu''ils ont fait. Avez-vous déjà tué 10 exemplaires de chacun d''entre eux ?', 0),
(323, 'frFR', 'Battez-vous avec acharnement, $N. Et ne désespérez pas, car le désespoir est la plus grande arme du mal.', 0),
(372, 'frFR', 'Vous n''avez pas encore accompli votre devoir, $C. Nous ne pouvons pas espérer mener à bien le plan de la Dame Sombre avec la Croisade Ecarlate qui harcèle nos soldats. Faites-les mourir et accomplissez votre devoir envers Sylvanas !', 0),
(380, 'frFR', 'Méfiez-vous du venin des araignées, $N. Si vous ressentez une vive brûlure, il peut être utile de la faire examiner.', 0),
(409, 'frFR', 'J''attends la preuve de votre allégeance, $C.', 0),
(421, 'frFR', 'Si vous voulez me prouver votre valeur, vous devez tuer 5 Calamars blancs de Moonrage. Accomplissez cette tâche, et je veillerai à ce que vos compétences soient mises au service de missions plus méritantes.', 0),
(434, 'frFR', 'Oui, $N ? Les choses se passent-elles bien avec Tyrion ? Il m''a mis au courant de la situation et je l''ai aidé à piéger Marzon pour qu''il se rende au château.$B$BMarzon a été une épine dans le pied de nombreuses personnes à Hurlevent, dont beaucoup sont des amis proches. Personne ne s''attaque à mes amis... pas s''ils savent ce qui est bon pour eux.$B$BC''est juste dommage que je rende indirectement service à Shaw et au SI:7 pendant ce temps. Enfin, tous les plans ne sont pas parfaits.', 0),
(455, 'frFR', 'Vous venez du Loch Modan ? Quelle est la situation des orcs à Algaz Gate ?', 0),
(486, 'frFR', 'Nos frères ne peuvent pas être réveillés tant qu''Ursal l''assassin n''a pas été tué, $N.', 0),
(487, 'frFR', 'La route n''est toujours pas sûre, $C. Partez en voyage et tuez 6 Ambushers de Gnarlpine et revenez me voir.', 0),
(504, 'frFR', 'Vous avez d''autres bellicistes à abattre, $N. Vous devriez être dans les montagnes pour accomplir votre tâche, pas ici avec votre arme rangée.', 0),
(505, 'frFR', 'Vous avez tué ces voyous du Syndicat, j''espère ?', 0),
(518, 'frFR', 'Je constate que votre tâche est inachevée, $N. Dois-je informer Sharlindra de votre inaptitude ?', 0),
(526, 'frFR', 'Avez-vous trouvé le fer lightforge dont vous avez besoin ?', 0),
(528, 'frFR', 'Vous avez vos ordres, $C. Arrêtez de lambiner ici à Tarren Mill alors qu''il y a du travail à faire ailleurs.', 0),
(539, 'frFR', 'Vous avez reçu l''ordre direct d''attaquer la mine d''Azureload. Vos raisons de flâner à Tarren Mill ont intérêt à être bonnes ou je vous décapiterai pour trahison.', 0),
(545, 'frFR', 'Avez-vous déjà réduit les patrouilles de Dalaran autour de leurs ruines ?', 0),
(549, 'frFR', 'N''avez-vous rien de mieux à faire que de vous tenir devant moi, $C ? En tant que Grand Exécuteur, j''ai des choses plus urgentes à faire que de regarder votre visage pourri.', 0),
(564, 'frFR', 'Les lions de montagne tuent nos chevaux à gauche et à droite et vous êtes là à vouloir parler du temps qu''il fait et de ce qui ne va pas.$B$BJe devrais me trouver un vrai héros. Plus de tueries et moins de bavardages.', 0),
(568, 'frFR', 'Nos efforts d''approvisionnement sont toujours entravés par la population indigène de rapaces, $C.', 0),
(578, 'frFR', 'Les trolls possédaient vraiment des objets magiques étonnants, $N. Et maintenant, j''ai peut-être l''occasion d''en ajouter un à ma vaste collection. Avez-vous réussi à trouver la source de la rumeur ?', 0),
(633, 'frFR', 'La cache d''explosifs doit être détruite !', 0),
(665, 'frFR', 'Ce n''est pas le moment de parler ! Les lunettes doivent être chargées avec le pouvoir de la pierre !', 0),
(677, 'frFR', 'Si vous n''avez pas encore accompli ma tâche, c''est que vous êtes peut-être un lâche dans l''âme et un novice dans la guerre.', 0),
(678, 'frFR', 'Vous hésitez. Pourquoi ? Vous avez fait preuve d''une grande force jusqu''à présent, $N. Ne me décevez pas maintenant.', 0),
(731, 'frFR', 'Le prospecteur est-il vivant ?', 0),
(739, 'frFR', 'Avez-vous des nouvelles du sort d''Agmond ? L''avez-vous retrouvé ?', 0),
(754, 'frFR', 'Ne tardez pas, $N. La souillure du Puits de Winterhoof doit être enlevée !', 0),
(758, 'frFR', 'Le puits de Thunderhorn est toujours contaminé, $N. S''il vous plaît, vous devez accomplir le rituel !', 0),
(764, 'frFR', 'La Venture Co. s''est vu refuser les droits d''exploitation minière ici à Mulgore, mais il semblerait qu''ils ne se contentent pas d''un refus. Nous, les taurens, ne sommes pas du genre à mâcher nos mots, et nous avons d''autres moyens de faire passer notre message.', 0),
(784, 'frFR', 'Vous avez des ordres, $N. La sécurité de Durotar est en jeu. Accomplissez la tâche qui vous est confiée, ou bien vous devrez baisser la tête de honte.$B$BFaites preuve d''honneur et battez les humains du donjon de Tiragarde.', 0),
(786, 'frFR', 'Les centaures se sont révélés être une nuisance constante pour la Horde. Leur intention d''assiéger notre patrie ne peut être tolérée.', 0),
(788, 'frFR', 'J''espère que vous n''êtes pas revenu pour essayer de me convaincre que vous avez accompli votre tâche, $N ? Non, bien sûr. J''aurais une meilleure opinion de vous.', 0),
(792, 'frFR', 'Pour faire vos preuves face à la Lame ardente, vous devez d''abord vaincre ses Familiers infâmes. Revenez me voir quand vous l''aurez fait.', 0),
(833, 'frFR', 'Les intrus à dos de chardon doivent être chassés de notre cimetière sacré, $N.', 0),
(849, 'frFR', 'Une fois la machine volante naine détruite, je ressentirai la douce satisfaction de la vengeance.', 0),
(863, 'frFR', 'Je peux vous aider ?', 0),
(870, 'frFR', 'Avez-vous visité les bassins oubliés, $N ? Avez-vous trouvé quelque chose ?', 0),
(871, 'frFR', 'Plus il faudra de temps pour mettre fin à ces attaques, plus il sera difficile d''approvisionner les habitants de la croisée des chemins.', 0),
(877, 'frFR', 'Avez-vous déjà visité l''oasis stagnante ? Y avait-il une fissure sous ses eaux ?', 0),
(878, 'frFR', 'Plus d''informations <snort>pour la Horde quand vous aurez tué les sages de Bristleback, $R. <snort>Pas un instant plus tôt ! Dents-de-manteau n''est pas un imbécile.', 0),
(887, 'frFR', 'Je ne veux même pas penser aux profits que j''ai perdus à cause des raids de pirates, et maintenant ils installent un camp sur le pas de ma porte ? Ça devient incontrôlable, Undermine doit faire quelque chose.', 0),
(905, 'frFR', 'Avez-vous visité les nids, $N ?', 0),
(908, 'frFR', 'Avez-vous réussi à localiser le noyau de la brasse ? Sans cela, nous n''aurons aucune idée de ce que le Marteau du crépuscule est en train de faire là-bas.', 0),
(909, 'frFR', 'Ah, bonjour à nouveau $N. Je lisais juste les vagues de la mer, comme je le fais toujours. Qu''est-ce qui vous amène à l''avant-poste ?', 0),
(910, 'frFR', 'On est arrivés ?', 0),
(911, 'frFR', 'Sommes-nous arrivés à ce stade ?', 0),
(924, 'frFR', 'La graine de démon existe toujours. Je peux sentir son pouvoir...', 0),
(934, 'frFR', 'Avec les druides, l''arbre-oracle et l''archidruide ont surveillé attentivement la croissance de Teldrassil. Mais bien que nous ayons un nouveau foyer, nos vies immortelles n''ont pas été restaurées.', 0),
(957, 'frFR', 'En vérité, $N, j''ai peur... Peur que votre venue - tout ceci - ne soit qu''une invention d''un esprit dérangé. Pouvez-vous savoir la torture que c''est ? I... S''il vous plaît, vous devez partir rapidement.', 0),
(976, 'frFR', 'Les Sentinelles ont un grand besoin de ravitaillement pour se renforcer à Sombrivage.', 0),
(984, 'frFR', 'Comment se passe votre recherche, $N ?', 0),
(985, 'frFR', 'Ne t''éloigne pas de ce qui doit être fait, mon enfant. Je sais à quel point l''idée de tuer les créatures de la forêt doit être répugnante, mais dans ce cas, c''est nécessaire. Aucun remède n''a été découvert contre la corruption qui s''est abattue sur la forêt, et nous devons faire tout ce qui est en notre pouvoir pour stopper sa progression jusqu''à ce qu''un remède soit trouvé.', 0),
(1022, 'frFR', 'Le tome du sanctuaire est un objet mystérieux. Ce n''est pas un livre au sens traditionnel du terme. Les feuilles du tome ont été bénies par Mel''Thandris elle-même, et il consigne dans ses pages des événements importants.$B$BIl m''est difficile de l''expliquer. Si vous vous rendez à l''autel, vous comprendrez.', 0),
(1025, 'frFR', 'Les furbolgs n''ont pas toujours été nos ennemis, $N. Mais les temps changent et la paix n''est plus de mise dans ces bois sombres.', 0),
(1048, 'frFR', 'Je n''ai peut-être pas été assez explicite dans mes ordres, $C. Je veux que le Haut Inquisiteur Whitemane soit tué une fois pour toutes. Et tant que vous y êtes, éliminez aussi ses hauts gradés.$B$BTuez ce fanatique, le commandant écarlate Mograine. Détruisez Hérode, le Champion écarlate. Et massacrez aussi le maître des chiens Loksey et ses sales clébards.$B$BMaintenant, partez !', 0),
(1053, 'frFR', 'La corruption au sein du monastère ne cessera pas tant que les fonctionnaires les plus haut placés n''auront pas été démis de leurs fonctions.$B$BAu nom de la Lumière, tuez le Haut Inquisiteur Whitemane, le Commandant Écarlate Mograine, Hérode, le Champion Écarlate et le Maître des Chiens Loksey. Une fois qu''ils seront tombés, la véritable cause pourra peut-être être ravivée. En attendant, quiconque croise le chemin de la croisade est en danger.$B$BPartez d’Austrivage et faites en sorte qu''il en soit ainsi !', 0),
(1057, 'frFR', 'Il reste encore beaucoup à faire pour que la vallée calcinée redevienne la forêt luxuriante qu''elle était autrefois.$B$BDébarrassez la région de ces menaces immondes, $N ! Ce n''est qu''alors que nous pourrons commencer à récupérer ce qui appartient à la nature.', 0),
(1062, 'frFR', 'La vallée de Greatwood se trouve au nord-ouest, $N. Allez-y. Faites peur à ceux qui voudraient piller cette terre !', 0),
(1071, 'frFR', 'Comment se passe la bataille de votre côté, $N ?', 0),
(1086, 'frFR', 'Vous devez trouver l''aéroport de la KapitalRisk s''il existe, $N.', 0),
(1087, 'frFR', 'Ici, canaliser la magie, c''est comme tirer de l''eau d''un puits avec un seau plein de trous.', 0),
(1103, 'frFR', 'Vous avez le sapta, $G frère:sœur; ?$B$BJe connais un autre qui a eu des problèmes après avoir vaincu l''esprit corrompu de l''eau - il semble qu''il ait attendu trop longtemps et qu''il soit sorti du monde des esprits trop rapidement à son goût. Je ne voudrais pas que cela arrive à quelqu''un d''autre, alors je vais attendre ici un peu pour m''assurer que personne d''autre n''a besoin de mon aide.', 0),
(1127, 'frFR', 'Avez-vous déjà ces mélanges de Zanzil, $N ?', 0),
(1140, 'frFR', 'J''ai entendu chuchoter un jour que l''histoire des satyres était liée à celle des elfes de la nuit, mais mes chers hôtes se sont montrés réticents à l''idée d''en parler.', 0),
(1147, 'frFR', 'Vu le nombre de voyageurs qui se rendent dans les plaines pour ces courses, je suis sûr que nous pourrons convaincre suffisamment de personnes en quête d''aventure de nous aider à repousser ces insectes. Mon groupe et moi ne pourrons pas partir tant que nous ne l''aurons pas fait.', 0),
(1168, 'frFR', 'Mok''Morokk dit à tous les ogres de rester et de garder cet endroit en sécurité. Je pense que les ogres doivent tuer l''armée du dragon noir et récupérer leur ancienne maison.$B$BAidez les ogres à retrouver leur maison. Aide les ogres à se venger.', 0),
(1175, 'frFR', 'Il est déjà assez difficile de débarrasser les épaves des coureurs sans avoir à les choisir parmi les morceaux d''animaux brûlés.', 0),
(1201, 'frFR', 'Avez-vous trouvé les infiltrés, $N ?', 0),
(1222, 'frFR', 'Avez-vous vu M. Ignatz ? Je l''ai envoyé dans le marais il y a quelque temps et il n''est pas revenu !', 0),
(1273, 'frFR', 'Avez-vous trouvé Reethe ?', 0),
(1324, 'frFR', 'Re-bonjour, $N. J''espère que cette aide ne vous dérange pas, mais il ne fallait pas que Hendel s''échappe, ou pire, qu''il meure.', 0),
(1367, 'frFR', 'Partez ! Les Magrams ne parlent pas aux faibles. Nous les tuons !$B$BSi tu veux me parler, montre-moi que tu es fort. Revenez après avoir tué de nombreux Gelkis.', 0),
(1368, 'frFR', 'Vos deux pieds foulent la terre de Gelkis. Vous n''êtes pas les bienvenus ici !$B$BProuvez que vous recherchez l''amitié des Gelkis. Tuez le centaure de Magram. Revenez quand le sol est mouillé par le sang de Magram.', 0),
(1382, 'frFR', 'Partez ! Les Gelkis ne veulent pas de vous ici. Partez maintenant !$B$BRevenez après avoir tué de nombreux Magram, et je vous parlerai.', 0),
(1386, 'frFR', 'Avez-vous peur des Kolkar ? Pourquoi ne les tuez-vous pas ? Vous avez peut-être oublié comment tuer. Dépêchez-vous de tuer les Kolkars avant qu''ils ne meurent !', 0),
(1396, 'frFR', 'Les créatures des marais se rapprochent, $N. S''il vous plaît, vous devez défendre le camp !', 0),
(1434, 'frFR', 'Un compagnon tauren m''a prévenu que les satyres n''étaient pas ce qu''ils semblaient être. Il pense qu''ils ont quelque chose de plus, que leur mal n''est qu''une déformation de leur vraie nature. Mais je n''ai rien vu de tel.$B$BJe n''ai vu que le massacre impitoyable des faibles et la corruption de ceux qui recherchent le pouvoir des ténèbres.$B$BJe continuerai à les anéantir jusqu''à ce que le Warchief m''en donne l''ordre. En attendant, je n''ai aucune pitié pour eux.', 0),
(1447, 'frFR', 'Je n''ai rien voulu dire en disant que tu étais un stupide $C. Nous sommes amis, n''est-ce pas ? Sans rancune ?', 0),
(1479, 'frFR', 'On est arrivés ?', 0),
(1487, 'frFR', '$N, nous, Disciples de Naralex, avons besoin de votre aide. Nos nombres diminuent avec notre maître emprisonné dans son cauchemar tordu.Nous n''avons pas les forces nécessaires pour faire face aux créatures corrompues qui hantent maintenant ces cavernes.$B$BI, implorez-vous, entrez dans les cavernes et faites la guerre aux créatures déviantes!', 0),
(1488, 'frFR', 'Gloire à la Horde, et mort à nos ennemis, $N !$B$BLes démons de Desolace représentent une menace plus grande que jamais. Mon espoir de retrouver le Warchief s''amenuise au fur et à mesure que ces créatures immondes apparaissent.$B$BJ''aimerais parfois n''avoir à affronter que le centaure.', 0),
(1558, 'frFR', 'Sommes-nous arrivés à ce stade ?', 0),
(1687, 'frFR', 'Sommes-nous arrivés à ce stade ?', 0),
(1690, 'frFR', 'De retour si tôt ? J''espère que tu as pu rendre la justice à ces bandits et voleurs du Wastewander comme je te l''avais demandé !', 0),
(1691, 'frFR', 'Avez-vous réussi à éliminer ces nomades comme je vous l''avais demandé ? La Compagnie des eaux de Gadgetzan élabore des plans basés sur votre succès ici ! Ne nous décevez pas, maintenant...', 0),
(1692, 'frFR', 'Bonjour, $C. Comment puis-je vous servir ?', 0),
(1703, 'frFR', 'Je vous salue, $C.', 0),
(1800, 'frFR', 'On est arrivés ?', 0),
(1884, 'frFR', 'Tu dois te dépêcher, $N. Détruisez les tas de juju !', 0),
(1950, 'frFR', 'Qu''attendez-vous ? J''ai besoin de ma phrase magique !', 0),
(1955, 'frFR', 'Vous devrez tuer ce démon pour enlever sa souillure de l''orbe, $N.', 0),
(1957, 'frFR', 'Vous n''avez pas tué le nombre requis de surtensions de mana, $N.', 0),
(2118, 'frFR', 'M''avez-vous apporté l''animal malade, $N ?$B$BSi vous ne parvenez pas à déclencher le piège, ne vous inquiétez pas : l''espoir de Tharnariun est éternel. Si vous avez besoin d''un autre piège, abandonnez votre tâche et revenez me voir.', 0),
(2138, 'frFR', 'Votre tâche est-elle terminée ?', 0),
(2139, 'frFR', 'En tuant la mère de la tanière infectée, on réduit la population d''oursons enragés qui pénètrent sur nos terres. Ne perdez pas de temps, $N.', 0),
(2240, 'frFR', 'Avez-vous quelque chose à signaler ?', 0),
(2358, 'frFR', 'Avez-vous les cornes du prince démoniaque ?', 0),
(2608, 'frFR', 'Lorsque vous serez prêt pour l''examen, /couchez-vous sur le sol et je commencerai la phlébotomie.', 0),
(2742, 'frFR', 'Rin''ji a peur !', 0),
(2767, 'frFR', 'Oui, je suis Oglethorpe Obnoticus, maître inventeur à votre service ! Y a-t-il quelque chose que je puisse faire pour vous aider ?', 0),
(2843, 'frFR', 'Il est prêt !', 0),
(2863, 'frFR', 'Le temps presse, $N ! Si vous n''êtes pas ici pour nous dire que vous avez éliminé les Alphas, alors vous perdez votre temps !', 0),
(2904, 'frFR', 'Eh ? Kernobee est vivant ?', 0),
(2929, 'frFR', 'La tâche est-elle terminée ? A-t-il demandé l''indulgence ? De clémence ??', 0),
(2932, 'frFR', 'Vous n''avez pas accompli ma tâche, $N.', 0),
(2936, 'frFR', 'Connaissez-vous le nom du dieu araignée ?', 0),
(2975, 'frFR', 'Faites vite, $N. Ou la tâche que j''ai demandée est-elle trop difficile ?', 0),
(2980, 'frFR', 'Avez-vous trouvé les ruines, $N ?', 0),
(2982, 'frFR', 'Méfiez-vous des Gordunni, $N. Leur magie semble faire des ravages sur la terre même où ils se trouvent.', 0),
(2988, 'frFR', 'Avez-vous fouillé les cages, $N ? Nous devons trouver Bec-tranchant !', 0),
(2994, 'frFR', 'Sauvez Bec-tranchant!', 0),
(2995, 'frFR', 'La clé est de garder les elfes de Highvale isolés. Avez-vous trouvé le pavillon ?', 0),
(3063, 'frFR', 'Les ailes des harpies de Northspring sont noires comme la nuit ; ne les quittez pas des yeux, car elles risquent de disparaître dans les ténèbres.', 0),
(3114, 'frFR', 'Ouais, qu''est-ce qui y a ? Plus fort, si ça vous gêne pas, $N. J''entends plus très bien après quelques bières.', 0),
(3362, 'frFR', 'J''aimerais voir de plus près ce cactus dans la vallée... Laissez-en une partie en un seul morceau, voulez-vous ?', 0),
(3379, 'frFR', 'Quelles sont les informations dont vous disposez ?', 0),
(3381, 'frFR', 'Je reste ici à la demande de mon maître. On m''a autorisé à demander le prix que je souhaite pour le transport jusqu''à sa tour. Pour l''instant, je ne demande que les deux plumes de chaque voyageur afin de pouvoir continuer à fabriquer mes flèches emblématiques.$B$BSi vous ne faites pas attention, j''augmenterai le prix. Que pensez-vous d''une demi-douzaine d''or ?$B$BOui, c''est ce que je pensais. Faites attention à vous et je maintiendrai le prix au même niveau.', 0),
(3453, 'frFR', 'Ne pas interrompre le processus de canalisation.', 0),
(3511, 'frFR', 'Vous êtes là ! Etonnant, $N. Avez-vous découvert le véritable nom ?', 0),
(3514, 'frFR', 'Nous ne pouvons pas autoriser l''Alliance sur nos terres, $N. Faites-le savoir.', 0),
(3630, 'frFR', 'Oui, oui, quels sont vos besoins auxquels je pourrais répondre aujourd''hui ? Il est clair que j''ai le temps de le faire puisque tout ce que je fais, c''est de rester ici pendant que notre ville bien-aimée gît dans un nuage de mort irradiée.', 0),
(3634, 'frFR', 'Oui, oui, quels sont vos besoins auxquels je pourrais répondre aujourd''hui ? Il est clair que j''ai le temps de le faire puisque tout ce que je fais, c''est de rester ici pendant que notre ville bien-aimée gît dans un nuage de mort irradiée.', 0),
(3636, 'frFR', 'Amnennar doit être éradiqué. Allez-y, vite.', 0),
(3701, 'frFR', 'Apportez-vous de nouvelles informations ?', 0),
(3901, 'frFR', 'Ceux qui tardent à s''acquitter de cette tâche risquent de finir par errer sans but, comme nos frères et sœurs tombés au village. Espérons que vous ferez mieux qu''eux, n''est-ce pas ?$B', 0),
(3907, 'frFR', 'Les flammes vont bientôt ravager ces terres. Hâtez-vous, $N !', 0),
(4001, 'frFR', 'Qu''est-ce qui vous amène sur ces terres sacrées ?', 0),
(4081, 'frFR', 'Qu''est-ce qu''il y a, $R ? Tu ne vois pas que j''ai un peloton à commander ?$B$B', 0),
(4082, 'frFR', 'Encore vous ? Je dois vous reconnaître, $N, que vous êtes tenace.', 0),
(4083, 'frFR', 'Le Calice spectral flotte dans les airs, descendant et remontant tout doucement… au rythme d''un cœur agonisant.', 0),
(4120, 'frFR', 'Tout ce qui est touché par le gel émet une étrange lueur verte... Je sens qu''il est maléfique, mais en même temps très puissant.', 0),
(4132, 'frFR', 'Le boucher de Blackrock a-t-il été éliminé ?', 0),
(4145, 'frFR', 'Muigin doit d''abord s''excuser avant que je ne lui adresse à nouveau la parole !', 0),
(4182, 'frFR', 'Comment se passe la chasse au dragon ?', 0),
(4245, 'frFR', 'Avez-vous pu aider A-Me ? Le boîtier en mithril que vous avez mentionné comme étant détruit était une bonne idée de ce qui n''allait pas. Je suis sûr que si vous le remplacez, elle se réactivera et pourra rentrer à la maison.', 0),
(4262, 'frFR', '<Jalinda semble regarder votre tête.>', 0),
(4263, 'frFR', 'Le démon est-il mort ?', 0),
(4265, 'frFR', 'Vous avez quelque chose à signaler, $N ?', 0),
(4285, 'frFR', 'Avez-vous visité le pylône, $N ?', 0),
(4287, 'frFR', 'Avez-vous visité le pylône, $N ?', 0),
(4288, 'frFR', 'Avez-vous visité le pylône, $N ?', 0),
(4322, 'frFR', 'Vous avez l''air épuisé, $N. Vous devriez peut-être vous asseoir près du feu et vous détendre.', 0),
(4421, 'frFR', 'La corruption qui y règne conduit les créatures à la folie...', 0),
(4482, 'frFR', 'Trente or, $R. Trente pièces d''or et les composants nécessaires.', 0),
(4491, 'frFR', 'Je me suis tellement inquiété pour Ringo...', 0),
(4521, 'frFR', 'Faites-moi un rapport après avoir accompli la tâche que je vous ai confiée.', 0),
(4701, 'frFR', 'Avez-vous découvert et traité la source de la menace mondiale ?', 0),
(4721, 'frFR', 'Vous connaissez vos ordres, $N.', 0),
(4724, 'frFR', 'Une fois la maîtresse de meute tuée, nous pourrons commencer à réduire le nombre de sentinelles worgs de la flèche et éventuellement progresser dans la ville.', 0),
(4740, 'frFR', 'Salutations $C - Que peuvent faire les Sentinelles pour vous aider aujourd''hui ? Peut-être êtes-vous ici pour vous renseigner sur la prime accordée à Murkdeep ?', 0),
(4771, 'frFR', 'N''oubliez pas, $N, que nous devons être tolérants tout en restant fidèles à nos convictions !', 0),
(4786, 'frFR', 'Un instant, $N...', 0),
(4811, 'frFR', 'Qu''avez-vous à dire sur ce cristal rouge ? Existe-t-il vraiment ?', 0),
(4906, 'frFR', 'S''il vous plaît, mettez fin à la souffrance des créatures de Gangrebois.', 0),
(4921, 'frFR', 'Avez-vous trouvé la moindre trace d''elle ? La douleur dans ma poitrine me dit que le pire est arrivé, mais j''ai l''espoir que vous la retrouverez saine et sauve.', 0),
(4961, 'frFR', 'Vous devrez tuer ce démon pour qu''il disparaisse définitivement de l''orbe, $N.', 0),
(5054, 'frFR', 'Va maintenant, $C. Cherchez Ursius.', 0),
(5055, 'frFR', 'Brumeran vous appelle, $N.', 0),
(5056, 'frFR', 'Shy-Rotam est audacieuse et impitoyable ; elle défendra son espèce avec un enthousiasme fervent.', 0),
(5063, 'frFR', 'Si vous n''avez pas tout ce dont j''ai besoin, vous me faites perdre mon temps.', 0),
(5067, 'frFR', 'Si vous n''avez pas tout ce dont j''ai besoin, vous me faites perdre mon temps.', 0),
(5068, 'frFR', 'Si vous n''avez pas tout ce dont j''ai besoin, vous me faites perdre mon temps.', 0),
(5092, 'frFR', 'Je veux que vous vous prépariez au pire, $N - creusez profondément. La tâche qui nous attend ne sera pas facile. Alors que nous rassemblons nos forces ici pour finalement frapper le Fléau, vous ferez partie de notre effort de progression pour les combattre ! La mission qui vous sera confiée à Sorrow Hill marquera le début de notre chemin vers la victoire !', 0),
(5098, 'frFR', 'Une fois les tours marquées, elles deviendront des cibles prioritaires pour notre attaque sur Andorhal. Je pense qu''une fois que nous aurons neutralisé les tours, la principale menace d''Andorhal apparaîtra. À partir de ce moment-là, nous aurons une lutte sans merci pour le contrôle de la ville !$B$BVous êtes de retour pour nous faire part de votre succès, n''est-ce pas ? N''oubliez pas non plus la torche de la balise, nous devons garder le contrôle de notre matériel.', 0),
(5121, 'frFR', 'Vous en saurez peut-être plus en lisant Winterfall Village, $N.', 0),
(5146, 'frFR', 'La fabrication de ce type d''armure à base de cuir exige de la patience et du dévouement. Une fois que vous avez jeté votre dévolu sur les éléments, vous ne pouvez plus leur tourner le dos. Apportez-moi la preuve de votre valeur et nous commencerons.', 0),
(5155, 'frFR', 'Comment se passe votre combat, $N ? Je sais que l''effusion de sang comme preuve d''honneur peut en dégoûter certains, mais vous devez comprendre que cela sert deux objectifs : vous me facilitez la tâche en réduisant leur nombre, et nous gagnons un respect mutuel qui ne fera que nous rendre plus forts dans les temps à venir.$B$BJ''espère que vous comprenez.', 0),
(5156, 'frFR', 'J''espère que vos recherches se dérouleront bien, $N. Je n''ai pas encore commencé à me diriger vers le nord, mais j''avoue que l''idée de croiser le chemin d''un infernal m''effraie un peu. Ces créatures n''ont pas de cerveau, mais elles sont tout de même assez intimidantes.', 0),
(5165, 'frFR', 'Les braseros doivent être éteints si nous voulons avoir l''espoir d''être préparés à une bataille bien plus importante. Entrer dans l''antre du dragon sans rien savoir est une entreprise insensée. Et c''est bien pire qu''un dragon. Le Conseil de l''Ombre est le seul responsable d''un grand nombre de crimes et d''atrocités. Nous devrons travailler rapidement si nous voulons les arrêter.', 0),
(5167, 'frFR', 'Un tel objet n''a jamais été fabriqué !', 0),
(5201, 'frFR', 'Les furbolgs semblent souffrir d''une telle paranoïa...', 0),
(5203, 'frFR', 'Vous avez l''air essoufflé, $N. Vous allez bien, ou quelque chose ne va pas ?', 0),
(5211, 'frFR', 'Les pauvres défenseurs de Comté-de-Darrow me crient dans mes rêves, $N. Vous devez les libérer !', 0),
(5251, 'frFR', 'Rappelez-vous, $N - nous devons être tolérants mais rigides dans nos croyances!', 0),
(5307, 'frFR', 'Avez-vous oublié la mission qui vous a été confiée, $N ?', 0),
(5521, 'frFR', 'Salutations, puissant $C ! Avez-vous apporté les jetons de valeur que je vous ai demandés ? Si vous me les remettez, je vous remettrai votre propre manteau chromatique de l''aube.', 0),
(5529, 'frFR', 'Allez à la Scholomance, $N. Éliminez ces enfants malades avant qu''ils ne grandissent !', 0),
(5535, 'frFR', 'Comment se passe votre recherche des alcools de haute volée, $C ?$B$BDe nombreux événements ont causé de grandes souffrances à toutes les races d''Azeroth, mais pour une raison ou une autre, ces esprits semblent être un fléau pour tous les peuples. Peut-être est-ce dû à leur désir constant d''utiliser la magie des arcanes - un tel désir est un signe avant-coureur de la Légion ardente, et nous savons à quoi cela peut mener.', 0),
(5542, 'frFR', 'Ne plains pas les chiens démoniaques, $R. Ce sont des abominations !', 0),
(5543, 'frFR', 'Ne sous-estimez pas la vermine ailée, $R. La peste leur a donné des capacités surnaturelles.', 0),
(5621, 'frFR', 'Nos sorts de Fortification sont très puissants, Delor. Ils permettent à nos compagnons d''encaisser des blessures de toutes sortes et de survivre dans des situations où ils tomberaient normalement. Mais ce n''est rien comparé à nos capacités de guérison. Il n''y a pas de plus grand guérisseur qu''un prêtre, il faut s''en souvenir. Votre seul pouvoir peut facilement renverser le cours d''une bataille.', 0),
(5624, 'frFR', 'Comme vous l''avez peut-être déjà appris, notre magie de guérison est vitale pour la survie de notre peuple en ces temps difficiles, en particulier pour les aventuriers et les héros qui prennent les armes et la magie pour repousser les menaces les plus diverses.$B$BVous feriez bien de toujours vous souvenir de l''importance de cette compétence. Associée à la Force d''âme, elle rendra vos compagnons bien plus aptes au combat, puisqu''ils seront capables de résister à un plus grand nombre de coups.$B$BNe laissez personne ignorer la puissance de votre magie.', 0),
(5625, 'frFR', 'Avez-vous trouvé Dolf, $N ?$B$BVous l''avez probablement déjà appris, mais notre capacité à guérir est très utile. Non seulement nous pouvons soigner les blessés, mais nous sommes aussi indispensables à la survie de tous les héros en herbe qui tentent de se faire un nom. Grâce à notre Force d''âme, qui nous permet d''encaisser plus de coups, et à notre magie de guérison, qui nous permet de les maintenir en vie, rien ne nous échappe !', 0),
(5648, 'frFR', 'La plupart des gens trouvent logique que les magies de guérison soient puissantes, mais peu comprennent à quel point elles le sont. Vous pouvez maintenir de nombreuses personnes en vie alors qu''elles devraient plutôt rencontrer leurs propres ancêtres. Cette magie de guérison, combinée à la capacité de Force d''âme, est une combinaison de sorts très puissante. Vous vous en souvenez. Elle est utile à toutes sortes de personnes : guerriers, mages et tout ce qui se trouve entre les deux.', 0),
(5713, 'frFR', 'Avez-vous vu la sentinelle Aynasha sur la route ? Elle est partie pour une mission importante, mais elle n''est pas encore revenue.', 0),
(5721, 'frFR', 'Je crois que j''ai entendu des fantômes dehors. Ils me murmurent des choses effrayantes...', 0),
(5723, 'frFR', 'Comment se passe votre recherche du gouffre ? Et des trognes ?$B$BIl ne faut pas laisser la menace perdurer, elle ne fera que nuire à nos frères orcs si elle continue.', 0),
(5727, 'frFR', 'Alors, $C ? A-t-il cru à notre stratagème ou les choses sont-elles plus graves que je ne l''avais d''abord estimé ?$B$BLe fait de prouver notre valeur à Neeru facilitera notre infiltration au sein du Conseil de l''ombre. Il aura de nombreuses informations que nous pourrons utiliser pour repérer ceux qui veulent détruire tout ce que nous avons construit à Durotar.', 0),
(5728, 'frFR', 'Les avez-vous trouvés, $N ? Les chefs de la lame tranchante.$B$BJe savais que le Conseil de l''ombre cherchait à me prendre Orgrimmar et toute la Horde, mais je n''avais pas réalisé à quelle vitesse ils avaient pu s''infiltrer dans la ville. Cette bête a tellement de bras... Nous pouvons les couper jusqu''à l''épuisement, mais nous ne serons pas plus avancés qu''au début. Je vais devoir demander à mes espions de redoubler d''efforts.', 0),
(5805, 'frFR', 'Je vous salue ! C''est un plaisir de vous rencontrer !$B$BJe vois que vous avez un bon spécial. Donnez-le moi et je vous offrirai quelque chose en échange.', 0),
(5821, 'frFR', 'Pourquoi est-ce que je me retrouve à attendre cette maudite caravane ?$B$B<Smeed a l''air éclairé.>$B$BAh oui, ils paient les factures. Vous les avez vus ?', 0),
(5842, 'frFR', 'Je vous salue ! C''est un plaisir de vous rencontrer !$B$BJe vois que vous avez un bon spécial. Donnez-le moi et je vous offrirai quelque chose en échange.', 0),
(5843, 'frFR', 'Bonjour ! C''est un plaisir de vous rencontrer !$B$BJe vois que vous avez un bon spécial. Donnez-le moi et je vous offrirai quelque chose en échange.', 0),
(5844, 'frFR', 'Je vous salue ! C''est un plaisir de vous rencontrer !$B$BJe vois que vous avez un bon spécial. Donnez-le moi et je vous offrirai quelque chose en échange.', 0),
(5863, 'frFR', 'Je suis très inquiète ! S''il vous plaît, faites attention !', 0),
(5943, 'frFR', 'Vous savez, si cette caravane venait à disparaître, je serais ruiné ! Vous n''êtes pas le porteur de mauvaises nouvelles à propos de la caravane, n''est-ce pas ?$B$B<Smeed s''essuie le front.>$B$BMerci à la déesse de la cupidité !', 0),
(5981, 'frFR', 'Vous devez continuer à faire vos preuves, $N.', 0),
(6002, 'frFR', 'Lorsque vous aurez relevé le défi qui se présente à vous, vous comprendrez pleinement ce que sont la force du corps et la force du cœur. En attendant, je ne peux pas vous aider davantage.', 0),
(6004, 'frFR', 'Comment ça se passe, $N ? Sont-ils plus forts que vous ne le pensiez ? J''espère que non. Si je dois aller jusqu''au bout, il va me falloir beaucoup plus de force que ce que je vous ai déjà demandé de faire.', 0),
(6023, 'frFR', 'Les avez-vous trouvés, $N ? Après m''être occupé d''eux deux, je peux entrer dans Âtreval pour examiner de plus près leur installation. Je ne peux pas le faire sans votre aide. S''il vous plaît, trouvez Radley et Durgen pour moi.', 0),
(6025, 'frFR', 'C''est une tâche dangereuse, $N. J''envie votre courage.', 0),
(6027, 'frFR', 'Ha, $N ! C''est bon de vous revoir. Avez-vous le Livre des Anciens ?', 0),
(6041, 'frFR', 'Il me reste du matériel pour fabriquer quelques bâtons supplémentaires de ce composé spécial. Faites savoir au vieux Smokey si vous en avez besoin.', 0),
(6124, 'frFR', 'Avez-vous terminé ce qui vous a été demandé par Alanndarian Nightsong of Auberdine ? Votre travail n''est pas complet s''il ne l''est pas.', 0),
(6129, 'frFR', 'Avez-vous terminé ce qui vous a été demandé par Tonga Runetotem à la Croisée des chemins ? Votre travail n''est pas complet s''il ne l''est pas.', 0),
(6132, 'frFR', 'Avez-vous vu ma sœur Melizza ? Elle est toujours en mouvement, ce qui lui vaut de nombreux ennuis.', 0),
(6136, 'frFR', 'T''ai-je dit dernièrement que je te détestais ?', 0),
(6143, 'frFR', 'J''entends encore leurs voix appeler à l''aide lorsque les nagas ont déchaîné leur chaos sur nous. Si je n''avais pas ce mauvais genou, je vous aiderais à tuer ces satanés nagas !$B$BEn général, on peut être sûr de les trouver dans les profondeurs des récifs coralliens, sous la surface... à l''affût... en train de comploter...', 0),
(6148, 'frFR', 'Quel est votre statut, $N ?', 0),
(6282, 'frFR', 'Ne vous méfiez pas de Charred Vale ; de nombreuses créatures maléfiques résident dans ces collines. Restez forts, $N, et vous vaincrez cette menace qui pèse sur notre peuple. Allez-y maintenant et frappez fort - nos enfants ne connaîtront jamais le mal de ce qui fut.', 0),
(6301, 'frFR', 'La destruction perpétuelle que cause la guerre, et ceux qui cherchent leurs intérêts dans ce massacre, m''endolorissent profondément. Pour aider le cycle de la vie à redonner une nouvelle jeunesse aux terres, j''ai besoin de Graines de Gaea. En avez-vous, $C ?', 0),
(6395, 'frFR', 'Nous devons respecter nos morts, $N. C''est l''une des façons dont nous nous distinguons du Fléau...', 0),
(6461, 'frFR', 'Hey mon, as-tu tué les mangeurs de sang poilus ? Je n''en crains aucun ici à Stonetalon mais je ne me promène pas ici la nuit... si tu vois ce que je veux dire !$B$BTant que je ne suis pas dans leur assiette, tout va bien.$B$BBonne chance à toi, $C !', 0),
(6481, 'frFR', 'Je crains que si nous ne nous débarrassons pas immédiatement de cette menace, tout Stonetalon sera perdu. La puissance d''un Terrien ne peut être égalée par aucun moyen. Au réveil, Goggeroc sera affaibli par son long sommeil, c''est l''occasion que vous devez saisir... allez-y $N !', 0),
(6482, 'frFR', 'Avez-vous vu mon frère Ruul ? Il est entré dans la forêt il y a quelques jours et n''est pas revenu...', 0),
(6544, 'frFR', 'Torek a été envoyé en mission contre l''avant-poste Silverwing. L''attaque a-t-elle été couronnée de succès ?', 0),
(6622, 'frFR', 'Un travail miraculeux, docteur. Tout simplement miraculeux.', 0),
(6624, 'frFR', 'Un travail miraculeux, docteur. Tout simplement miraculeux.', 0),
(6626, 'frFR', 'Comment se passe la chasse, $N ? En voyant ce petit échantillon de la puissance de ce diplomate, je n''ai plus aucun doute sur le fait que le Fléau est l''une des plus grandes menaces que le monde ait jamais connues.', 0),
(6822, 'frFR', 'Votre succès dans le noyau fondu vous attend, $N.', 0),
(6846, 'frFR', 'Mes troupes sont ravitaillées et prêtes à l''assaut. Nous avons juste besoin des ordres de Noreg Stormpike et je les enverrai dans la mêlée !', 0),
(7046, 'frFR', 'Si vous souhaitez recommencer le rituel, abandonnez notre première tentative et parlez-moi à nouveau.', 0),
(7064, 'frFR', 'Je préférerais mener cette bataille seul, mais nous n''avons pas d''autre choix. Nous avons besoin de plus puissants, et les races d''Azeroth ont prouvé sans aucun doute qu''elles peuvent vaincre de telles choses lorsqu''elles travaillent ensemble. C''est donc vers vous que nous nous tournons pour obtenir de l''aide.$B$BJ''espère seulement qu''elle sera suffisante.$B$BZaetar, le frère de Remulos, a apporté beaucoup de souffrances à ce monde, et a fini par causer sa propre mort. J''espère ne pas avoir causé davantage de morts en vous demandant de nous aider.', 0),
(7065, 'frFR', 'Je ressens le poids d''imposer mon plaidoyer aux races mortelles, mais nous n''avons pas d''autre choix. Les races d''Azeroth ont prouvé sans l''ombre d''un doute qu''elles peuvent surmonter de telles choses lorsqu''elles travaillent ensemble, c''est donc à elles que je demande de l''aide.$B$BJ''espère seulement que cela suffira.$B$BZaetar, le frère de Remulos, a apporté de nombreuses souffrances à ce monde, et a finalement causé sa propre mort. Il y a là une leçon pour nous tous, si nous sommes assez sages pour la voir.', 0),
(7081, 'frFR', '$N, vous n''avez pas encore attaqué un cimetière. Revenez à moi quand cette tâche sera terminée!', 0),
(7082, 'frFR', 'Attaquez un cimetière tenu par l''Alliance !', 0),
(7101, 'frFR', 'Vous n''avez pas encore attaqué de bunker, $N ! Vous attendez que d''autres s''emparent de votre gloire ?', 0),
(7122, 'frFR', 'Vous n''avez pas encore capturé la mine, $N !$B$BUne fois que nous aurons pris le contrôle d''une mine, il sera beaucoup plus facile d''en extraire des minerais et des fournitures.', 0),
(7124, 'frFR', 'Vous n''avez pas encore capturé de mine, $N ! Trouvez-en une que nous ne contrôlons pas et battez son chef !', 0),
(7141, 'frFR', 'Allez, $N. Va dans la vallée d''Alterac et bats le général orc !', 0),
(7224, 'frFR', 'Comment se passe la chasse, $N. Avez-vous des restes d''armure pour moi ?', 0),
(7281, 'frFR', 'Comme il doit souffrir de rester parmi les vivants alors que son frère bien-aimé est monté à la perfection.', 0),
(7282, 'frFR', 'C''est le cœur lourd que je donne cet ordre, soldat.', 0),
(7301, 'frFR', 'Y a-t-il quelque chose que j''aimerais entendre ?', 0),
(7302, 'frFR', 'État de la chasse, soldat ?', 0),
(7361, 'frFR', 'Ils cherchent à nous exterminer ? Ce sont eux qui seront exterminés.', 0),
(7362, 'frFR', 'Je me fiche de savoir d''où viennent les cheveux, $R.', 0),
(7363, 'frFR', 'Oui, c''est vrai. Mon frère est un humain. Honteux... Une tache sur mon dossier presque immaculé.', 0),
(7366, 'frFR', 'Benedictus ! Je ne suis qu''une tache dans l''ombre de sa grandeur. Louez-le !', 0),
(7401, 'frFR', 'Je fais de l''ironie en gros, soldat.', 0),
(7481, 'frFR', 'Mon associée, l''érudite elfe de la nuit Runethorn, recrute ses alliés pour cette tâche.', 0),
(7604, 'frFR', 'Avons-nous un accord ?', 0),
(7647, 'frFR', 'L''esprit du chargeur déchu vous regarde d''un air triste. Des yeux tristes, presque creux, vous regardent comme si tout espoir était perdu pour lui.', 0),
(7723, 'frFR', 'Vous les avez pilonnés ?', 0),
(7724, 'frFR', 'Avait-il raison ? Cela sort-il de leur croupion ?', 0),
(7789, 'frFR', 'Le sang de nos ennemis est une marque d''honneur. Avez-vous une telle marque ?', 0),
(7822, 'frFR', 'Les stocks de mageweave s''épuisent et nous avons besoin de votre aide pour les reconstituer ! En comptant sur l''ensemble de la communauté, il nous suffirait d''un don de 60 pièces de tissu de mageweave de votre part pour nous permettre d''atteindre notre objectif. Une telle générosité ne passerait pas inaperçue à Thunder Bluff, je vous l''assure !$B$BSi vous avez sur vous les soixante pièces de mageweave et que vous êtes prêts à en faire don, je peux vous les prendre dès maintenant.', 0),
(7828, 'frFR', 'Montrez-leur la puissance de Revantusk !', 0),
(7829, 'frFR', 'Videz votre tête de toute pensée impure, $R. Ne faites plus qu''un avec la nature !', 0),
(7843, 'frFR', 'Qu''est-ce qui se passe ?', 0),
(7844, 'frFR', 'Les devins et les scalpeurs de Vilebranch habitent la région nord-nord-est des Hinterlands.', 0),
(7861, 'frFR', 'Avez-vous des nouvelles de Jintha''alor ?', 0),
(7862, 'frFR', 'Vous êtes ici pour l''offre d''emploi ?', 0),
(7874, 'frFR', 'Le sang de nos ennemis est une marque d''honneur. Avez-vous une telle marque ?', 0),
(7875, 'frFR', 'Le sang de nos ennemis est une marque d''honneur. Avez-vous une telle marque ?', 0),
(7876, 'frFR', 'Le sang de nos ennemis est une marque d''honneur. Avez-vous une telle marque ?', 0),
(7882, 'frFR', 'Les travailleurs de la foire ne se contentent pas de balayer les ordures et de marteler les pics ! Ils participent également à la garde du carnaval lors de ses déplacements et, à cette fin, ils ont toujours besoin de bonnes et solides jerricanes d''armure.$B$BSi vous fabriquez une armure en cuir robuste et que vous me l''apportez, je m''assurerai qu''elle parvienne aux bonnes personnes. Je vous donnerai aussi des billets pour la Darkmoon Faire en échange.', 0),
(7883, 'frFR', 'Yebb Nebblegear cherche à ajouter de nouveaux talents à son émission, et il est à la recherche du plus grand gnome du monde. Connaissez-vous des gnomes de taille considérable ?$B$BAvant de trouver le gnome, il veut préparer son costume. Je pense qu''un harnais barbare serait une bonne base pour le costume ; pouvez-vous fabriquer quelques harnais et me les apporter ? Faites-le, et j''aurai une pile de billets pour la Darkmoon Faire pour vous...', 0),
(7900, 'frFR', 'Les enfants adorent les jouets ! Et quelle que soit leur race, j''ai constaté que tous les enfants adorent les jouets en peluche fabriqués à partir de peaux d''ours déchirées !$B$BVous pouvez obtenir ces peaux auprès des ours d’Orneval ou de Hautebrande. Apportez-m''en un tas et vous gagnerez un tas de billets pour la Darkmoon Faire !', 0),
(7936, 'frFR', 'Allez-y, allez-y, allez-y ! Si vous avez des billets de la Darkmoon Faire que vous aimeriez échanger, dites-le ! Vous pouvez échanger des billets de différentes valeurs contre des prix merveilleux et fantastiques. Ne soyez pas timide, essayez !', 0),
(7981, 'frFR', 'Allez-y, allez-y, allez-y ! Si vous avez des billets de la Darkmoon Faire que vous aimeriez échanger, dites-le ! Vous pouvez échanger des billets de différentes valeurs contre des prix merveilleux et fantastiques. Ne soyez pas timide, essayez !', 0),
(8057, 'frFR', 'Vous avez les Paragons of Power de Zul''Gurub ? Ces bracelets valent le coup, $N. Faites-moi confiance !', 0),
(8063, 'frFR', 'Recherchez la folie de Zul''Gurub et éclipsez-la avec la vôtre, $N ! Cela est synonyme de succès, et le succès est synonyme de récompense ! Ne laissez pas le Dieu du Sang régner à nouveau en maître !', 0),
(8065, 'frFR', 'Vous avez les Paragons du pouvoir de Zul''Gurub ? La tunique du haruspex vaut bien l''effort que vous aurez à faire.', 0),
(8073, 'frFR', 'Bienvenue sur l''île, $N... êtes-vous revenu triomphalement avec les Paragons du Pouvoir à vos côtés ?', 0),
(8080, 'frFR', 'Avez-vous les marques d''honneur, $N ? La Ligue d''Arathor ne peut pas mener une bataille décente sans elles...', 0),
(8081, 'frFR', '$N, la League of Arathor a pour mission permanente de vous faire rentrer dans le bassin d''Arathi, de vous procurer plus de caisses de ressources et de me les apporter.', 0),
(8119, 'frFR', '<Maywiki montre votre talisman.>$B$BRegarde ça, $N ! Il s''est animé. Les esprits dansent autour de l''orbe.$B$BDonnez-le à Maywiki pour qu''elle puisse faire un dernier ajustement.', 0),
(8124, 'frFR', '$N, les Defilers ont pour mission permanente de rentrer dans le bassin d''Arathi, de se procurer plus de caisses de ressources et de me les apporter.', 0),
(8149, 'frFR', 'Avez-vous fait le voyage jusqu''à la tombe d''Uther et y avez-vous déposé le tribut ?$B$BCe voyage peut s''avérer dangereux pour les aventuriers les moins expérimentés ; un moyen plus sûr de s''y rendre, relativement parlant, serait de voyager vers le nord depuis la rivière qui traverse Hautebrande jusqu''aux Maleterres. Elle s''écoule d''un lac adjacent à la colline du chagrin ; voyagez vers l''ouest à travers les collines, en évitant la tombe adjacente... qui est infestée par le Fléau.', 0),
(8150, 'frFR', 'Avez-vous fait le voyage jusqu''au monument de Grom et y avez-vous déposé son hommage ?$B$BLe site où se trouve le monument est encore touché par la souillure de la Légion ardente. Si vous êtes moins expérimenté dans le domaine de l''aventure, soyez sur vos gardes lorsque vous vous approcherez du monument.', 0),
(8157, 'frFR', '$N, la League of Arathor a pour mission permanente de vous faire rentrer dans le bassin d''Arathi, de vous procurer plus de caisses de ressources et de me les apporter.', 0),
(8158, 'frFR', '$N, la League of Arathor a pour mission permanente de vous faire rentrer dans le bassin d''Arathi, de vous procurer plus de caisses de ressources et de me les apporter.', 0),
(8159, 'frFR', '$N, la League of Arathor a pour mission permanente de vous faire rentrer dans le bassin d''Arathi, de vous procurer plus de caisses de ressources et de me les apporter.', 0),
(8163, 'frFR', '$N, les Defilers ont pour mission permanente de rentrer dans le bassin d''Arathi, de se procurer plus de caisses de ressources et de me les apporter.', 0),
(8164, 'frFR', '$N, les Defilers ont pour mission permanente de rentrer dans le bassin d''Arathi, de se procurer plus de caisses de ressources et de me les apporter.', 0),
(8165, 'frFR', '$N, les Defilers ont pour mission permanente de rentrer dans le bassin d''Arathi, de se procurer plus de caisses de ressources et de me les apporter.', 0),
(8225, 'frFR', '* Whir * * Cliquez *$B$BI cherchez des poissons rares que Fishmaster Bluegill va cataloguer. Si vous m''apportez un Brownell''s Blue Striped Racer, je vous offrirai cette belle récompense.$B$B* Zzzap * * Whir *', 0),
(8243, 'frFR', 'Votre nouveau statut au sein de la tribu vous donne accès à certains de nos breuvages plus puissants.  Regardez... ces mixtures sont fortes en mojo, bénies par Zanza et conviennent aux aventuriers de tous horizons !$B$BJe vais vous permettre de choisir l''une des trois que je propose. En échange, je demande une marque d''honneur zandalar.  Veuillez noter que les effets d''un seul breuvage à la fois peuvent habiter votre esprit.$B$BDites-moi quand vous serez prêt à faire l''échange !', 0),
(8258, 'frFR', 'Le temps presse, $N - avez-vous réussi à arrêter la menace du Chevalier Noir ?', 0),
(8280, 'frFR', 'Les grévistes de la drague constituent une menace sérieuse et doivent être traités rapidement !', 0),
(8294, 'frFR', 'Le sang de nos ennemis est une marque d''honneur. Avez-vous une telle marque ?', 0),
(8311, 'frFR', 'As-tu déjà fini de faire la chasse aux bonbons ? Je suis triste de ne pas pouvoir y aller parce que je suis malade, mais le fait que tu m''aides me rassure un peu...', 0),
(8356, 'frFR', 'Pas de bonbons tant que tu n''as pas fléchi pour moi, $N...', 0),
(8357, 'frFR', 'Tu sais danser, n''est-ce pas ? Essaie de mettre ton pied droit en avant... puis ton pied droit en arrière... ton pied droit en avant... secoue tout ça...', 0),
(8359, 'frFR', 'Pas de bonbons tant que tu n''as pas fléchi pour moi, $N...', 0),
(8360, 'frFR', 'Tu sais danser, n''est-ce pas ? Essaie de mettre ton pied droit en avant... puis ton pied droit en arrière... ton pied droit en avant... secoue tout ça...', 0),
(8366, 'frFR', 'De retour si tôt ? J''espère que vous avez donné à ces voyous de Southsea une leçon qu''ils ne sont pas prêts d''oublier.', 0),
(8411, 'frFR', 'Où sont les éléments ?', 0),
(8424, 'frFR', 'Les ombres ne sont pas faciles à vaincre, n''est-ce pas ? Mais vous êtes un guerrier, et vous triompherez ou périrez en essayant.', 0),
(8428, 'frFR', 'La bataille dans le goulet des Chanteguerres contre les Sentinelles d''Aile-argent est d''une grande importance. Sous le prétexte de protéger une forêt qui ne lui appartient pas, l''Alliance cherche à refuser à la Horde l''une de ses plus grandes ressources en bois.$B$BNe la laissez pas faire, $N ! Revenez me voir quand vous aurez la preuve que vous avez bien servi la Horde !', 0),
(8429, 'frFR', 'La bataille dans le goulet des Chanteguerres contre les Sentinelles d''Aile-argent est d''une grande importance. Sous le prétexte de protéger une forêt qui ne lui appartient pas, l''Alliance cherche à refuser à la Horde l''une de ses plus grandes ressources en bois.$B$BNe la laissez pas faire, $N ! Revenez me voir quand vous aurez la preuve que vous avez bien servi la Horde !', 0),
(8460, 'frFR', 'Continuez, $N. Si vous voulez gagner notre confiance, vous devrez faire vos preuves.', 0),
(8464, 'frFR', 'Nous apprécions beaucoup ce que vous avez fait pour les Timbermaw, $N. La poursuite de vos efforts vous vaudra certainement la confiance et le respect de ma tribu.', 0),
(8481, 'frFR', 'Tu es revenu parmi nous, $N... cela signifie-t-il que le démon a été tué ?', 0),
(8484, 'frFR', '$C, vous êtes accueilli dans mon domaine.Forgefer devrait toujours être considéré comme un foyer pour un héros tel que vous. Maintenant, quelles affaires avez-vous avec moi?', 0),
(8485, 'frFR', 'Les salutations du warchief vous sont accordées, $C. Vos actes renforcent la Horde en ces temps troublés. Qu''avez-vous à me dire ?', 0),
(8493, 'frFR', 'De retour, $C ? C''est remarquable ! Les barres que vous avez fournies jusqu''à présent vont vraiment nous aider à fabriquer toutes sortes de choses pour la guerre. Je sais, par exemple, que le cuivre sera utilisé pour les pièces des réservoirs à vapeur qui sont en cours de construction, ainsi que pour une petite flotte d''autogires que nous prévoyons de déployer si le temps le permet.$B$BNe vous laissez pas tromper par les piles, nous avons encore besoin de barres de cuivre si vous pouvez en procurer pour l''effort de guerre de l''Ahn''Qiraj. Pouvez-vous nous aider ?', 0),
(8494, 'frFR', 'Si vous avez ces vingt barres de fer, je ne veux pas savoir où vous les avez cachées !', 0),
(8499, 'frFR', 'Oh, un envoi de mon frère ? Splendide ! La chance me sourit vraiment aujourd''hui !', 0),
(8503, 'frFR', 'Ce n''est pas vrai ! Je n''enlèverais jamais d''épines de mer du haut des piles ici. On pourrait être tenté de le faire, étant donné que c''est pratiquement une panacée d''une grande utilité utilitaire. *tousse* Vous n''auriez pas l''herbe à poux dont nous avons parlé tout à l''heure ?', 0),
(8506, 'frFR', 'Bienvenue, $C. Notre collection s''agrandit, mais nous avons encore besoin de lotus violet. S''il vous est encore possible d''en récolter d''autres, je vous prie de le faire et de me les rapporter ici.', 0),
(8517, 'frFR', 'Avez-vous les vingt bandages en lin dont j''ai besoin, $C ?', 0),
(8527, 'frFR', 'Re-bonjour $C. Je vois bien que vous êtes passionnée par tout ça. Donc je suppose que vous voulez m’apporter vingt autres rôtis de raptor. Parfait. Faites donc. Je vous reverrai quand vous reviendrez avec la marchandise.', 0),
(8546, 'frFR', 'Oui, je suis content que tu sois là, mon. Tu m''as déjà aidé, et maintenant j''ai encore besoin de ton aide. Nous cherchons encore des barres de mithril pour l''effort de guerre ; nous allons fabriquer beaucoup d''armures, d''armes et d''objets pour écraser les insectes à Ahn''Qiraj.$B$BAlors si tu es un vrai ami, tu me ramènes des piles de barres de mithril. Je prends tout ce que tu as jusqu''à ce que nous ayons atteint notre quota. Tu en as pour moi maintenant ?', 0),
(8548, 'frFR', 'Il est dans notre intérêt de garder nos alliés les plus fidèles bien équipés, $N.', 0),
(8560, 'frFR', 'Avez-vous apporté les composants dont j''ai besoin, $N ?', 0),
(8581, 'frFR', 'Pele''keiki sait que tu es venu pour l''aider. Apportez beaucoup de fleurs de feu et rendez-le très heureux. Pele''keiki peut fabriquer de grosses bombes avec les fleurs de feu. Il les larguera sur les insectes depuis sa chauve-souris au-dessus d''Ahn''Qiraj lorsque la guerre éclatera. Mais Pele''keiki a besoin de plus de fleurs de feu, $C !$B$BTu vas apporter à Pele''keiki cette fleur de feu, très vite. Reviens avec au moins autant que la dernière fois, et Pele''keiki sera content.', 0),
(8583, 'frFR', 'En fait, il semble que nous ayons besoin d''encore plus de lotus violet, $C. Bien que mes propres études n''aient pas encore permis de déterminer une nouvelle application utile pour cette plante, il existe des méthodologies éprouvées qui doivent encore être employées.$B$BJ''ai besoin que vous alliez une fois de plus sur le terrain et que vous récoltiez au moins vingt échantillons de lotus violet. Renvoyez-les-moi ici.', 0),
(8589, 'frFR', 'C''est vrai, $C, j''ai toujours besoin de plus de cuir lourd. Les demandes des généraux et de leurs quartiers-maîtres semblent infinies. Et ce n''est rien comparé à ce que demandent les maîtres du zeppelin !$B$BIl faut que j''atteigne mon quota au plus vite. $N, apportez-moi d''autres piles de cuir lourd dès que possible !', 0),
(8592, 'frFR', 'M''avez-vous apporté les composants que j''ai demandés, $N ?', 0),
(8593, 'frFR', 'Avez-vous apporté les composants dont j''ai besoin, $N ?', 0),
(8596, 'frFR', 'Vous avez acquis les articles que j''ai demandés, $N ?', 0),
(8601, 'frFR', 'Les préparatifs pour la guerre imminente à Ahn''Qiraj se poursuivent, $C. Cependant, pour que nous ne prenions pas de retard, ou du moins que je ne sois pas celui qui nous en fait prendre, je veux que vous rameniez une autre pile de cuir robuste. Votre attention rapide à ce sujet sera grandement appréciée, $N.', 0),
(8605, 'frFR', 'Heureux de vous revoir, $C. Nous sommes toujours en train de préparer l''effort de guerre et j''ai besoin de toute l''aide que vous pouvez m''apporter pour rassembler des pansements en laine. Toute aide sera grandement appréciée. J''espère seulement que nos efforts seront suffisants. J''ai perdu trop d''âmes nobles sur les champs de bataille d''hier pour ne pas faire tout ce qui est en mon pouvoir pour que cela ne se reproduise pas.', 0),
(8608, 'frFR', 'Vous êtes revenu ? C''est intéressant. Comme vous le voyez, je continue à collecter des fonds pour l''effort de guerre de l''Ahn''Qiraj. J''ai donc besoin que vous alliez une fois de plus chercher une pile de bandages en mageweave pour moi. J''attends votre retour avec impatience, $C.', 0),
(8610, 'frFR', 'Le moment où nous nous lancerons tête baissée dans la conflagration d''Ahn''Qiraj, prêtre, se rapproche de plus en plus. Mais nous devons d''abord rassembler nos forces et nous préparer à survivre à l''assaut des insectes et de leurs maîtres.$B$BSi vous êtes de nouveau ici, vous souhaitez certainement apporter une nouvelle contribution à l''effort de guerre en fournissant des bandages en toile de jute. Faites-le dès que possible et revenez me voir.', 0),
(8612, 'frFR', 'Comme vous pouvez le voir, $C, nous devons encore emballer plus de nourriture pour les soldats. Je ne sais pas si vous avez déjà participé à une guerre, mais une fois passé le choc initial du champ de bataille, on peut avoir très faim. Vous avez fait du bon travail la dernière fois, alors je m''attends à ce que vous fassiez aussi bien, sinon un peu plus vite, pour me procurer une autre pile de ces steaks de loup maigres.', 0),
(8614, 'frFR', 'Comme vous pouvez le constater, nous avons encore besoin de beaucoup de poissons. Les combattants de la prochaine guerre d''Ahn''Qiraj auront besoin de beaucoup de nourriture, alors je dois récupérer toutes les sérioles tachetées que je peux. Si vous les attrapez, que vous les cuisinez et que vous me les rapportez, je vous remercierai et je remercierai la Horde.', 0),
(8621, 'frFR', 'Vous avez acquis les articles que j''ai demandés, $N ?', 0),
(8622, 'frFR', 'Vous avez acquis les articles que j''ai demandés, $N ?', 0),
(8623, 'frFR', 'Vous avez acquis les articles que j''ai demandés, $N ?', 0),
