(8691, 'frFR', 'As-tu apporté les matériaux pour la cape, $N ?', 0),
(8692, 'frFR', 'As-tu apporté les matériaux pour la cape, $N ?', 0),
(8695, 'frFR', 'As-tu apporté le matériel pour la cape, $N ?', 0),
(8698, 'frFR', 'Tu m''as apporté la bague et le matériel, $N ?', 0),
(8700, 'frFR', 'Tu m''as apporté la bague et le matériel, $N ?', 0),
