(9010, 'frFR', 'Conformément à notre accord, êtes-vous prêt à nous remettre vos pièces de Shadowcraft en échange de votre nouvelle casquette et de votre nouvelle tunique de Darkmantle ?', 0),
(9011, 'frFR', 'Conformément à notre accord, êtes-vous prêt à nous remettre vos éléments en échange de votre nouvelle coiffe et de votre nouvelle veste des Cinq Tonnerres ?', 0),
(9012, 'frFR', 'Conformément à notre accord, êtes-vous prêt à remettre vos pièces de Dreadmist en échange de votre nouveau masque et de votre nouvelle robe de Deathmist ?', 0),
(9014, 'frFR', 'Conformément à notre accord, êtes-vous prêt à remettre vos pièces de magister en échange de votre nouvelle couronne et de vos nouvelles robes de sorcier ?', 0),
(9016, 'frFR', 'Tu es revenu et je vois dans tes yeux que tu as beaucoup à me dire, $N. Occupons-nous d''abord de ta récompense.', 0),
(9018, 'frFR', 'Tu es revenu et je vois dans tes yeux que tu as beaucoup à me dire, $N. Occupons-nous d''abord de ta récompense.', 0),
(9019, 'frFR', 'Tu es revenu et je vois dans tes yeux que tu as beaucoup à me dire, $N. Occupons-nous d''abord de ta récompense.', 0),
(9020, 'frFR', 'Tu es revenu et je vois dans tes yeux que tu as beaucoup à me dire, $N. Occupons-nous d''abord de ta récompense.', 0),
(9021, 'frFR', 'Tu es revenu et je vois dans tes yeux que tu as beaucoup à me dire, $N. Occupons-nous d''abord de ta récompense.', 0),
(9033, 'frFR', 'Devoir, honneur, dévouement... Que signifient ces mots pour vous ?', 0),
(9051, 'frFR', 'Avez-vous réussi à apaiser la grande bête ?', 0),
(9073, 'frFR', 'M''as-tu apporté ce que je veux ?', 0),
(9075, 'frFR', 'M''as-tu apporté ce que je veux ?', 0),
(9081, 'frFR', 'Apportez-moi le matériel et arrêtez de me faire perdre mon temps, $C.', 0),
(9082, 'frFR', 'Comment voulez-vous que je fasse quoi que ce soit sans les éléments que j''ai demandés ?', 0),
(9083, 'frFR', 'Comment voulez-vous que je fasse quoi que ce soit sans les éléments que j''ai demandés ?', 0),
