(9092, 'frFR', 'Le coût du matériel est élevé, mais vite oublié.', 0),
(9114, 'frFR', 'M''as-tu apporté les réactifs, mon enfant ?', 0),
(9115, 'frFR', 'M''as-tu apporté les réactifs, mon enfant ?', 0),
(9123, 'frFR', 'Aucun d''entre eux n''est entré dans Naxxramas et n''a survécu pour raconter l''histoire.', 0),
